    curves = {name: partial_dependence(champion_prob, X_HOLD, FEATURES.index(name), GRID)
              for name in PD_FEATURES}
    for a, g in enumerate(GRID):
        print(f"  {g:>+6.1f}  " + "  ".join(f"{curves[name][a]:>16.4f}" for name in PD_FEATURES))


